INSERT INTO "account" ("id", "email", "passwordhash", "createdat", "username") VALUES (1, 'demo@example.com', '$2b$10$example.hash.for.demo.user', '2025-07-25T18:33:53.532Z', 'Player1');
INSERT INTO "account" ("id", "email", "passwordhash", "createdat", "username") VALUES (2, 'test@example.com', '$2b$10$yb93T.Tv2FUUl/2z2JBEMOtSgb3MoYuk5Bnl04RMzz.yXRa24RY.i', '2025-07-25T18:36:56.020Z', 'Player2');
INSERT INTO "account" ("id", "email", "passwordhash", "createdat", "username") VALUES (3, 'mandi@mandimay.com', '$2b$10$22nmYnZy9p1Bme3MIOCNrOcDDtnSG3/eQADFozKsIQuT9.s/F3hke', '2025-07-25T23:40:59.597Z', 'colormerad');
INSERT INTO "account" ("id", "email", "passwordhash", "createdat", "username") VALUES (4, 'pwilliams0530@gmail.com', '$2b$10$.ujpeQPRm/vXNx.y.6YBh.iNQN4HLMKrLbZCYK8xL1wVQfPa2VTK6', '2025-07-29T03:15:37.001Z', 'Xero');
INSERT INTO "class" ("id", "name", "description", "strengthbonus", "dexteritybonus", "constitutionbonus", "intelligencebonus", "wisdombonus", "charismabonus", "createdat", "updatedat") VALUES (1, 'Bardbarian', 'They sing songs of blood and biceps. The louder the ballad, the stronger the blow.', 15, 12, 14, 8, 8, 10, '2025-07-29T04:22:53.890Z', '2025-07-29T04:22:53.890Z');
INSERT INTO "class" ("id", "name", "description", "strengthbonus", "dexteritybonus", "constitutionbonus", "intelligencebonus", "wisdombonus", "charismabonus", "createdat", "updatedat") VALUES (2, 'Cheesemancer', 'Wields the power of dairy-based devastation. Foes are often grated... and melted.', 8, 10, 10, 14, 12, 13, '2025-07-29T04:22:53.890Z', '2025-07-29T04:22:53.890Z');
INSERT INTO "class" ("id", "name", "description", "strengthbonus", "dexteritybonus", "constitutionbonus", "intelligencebonus", "wisdombonus", "charismabonus", "createdat", "updatedat") VALUES (3, 'Owl Knight', 'Sees all. Knows more. Hoots dramatically before every battle.', 13, 12, 14, 10, 13, 8, '2025-07-29T04:22:53.890Z', '2025-07-29T04:22:53.890Z');
INSERT INTO "class" ("id", "name", "description", "strengthbonus", "dexteritybonus", "constitutionbonus", "intelligencebonus", "wisdombonus", "charismabonus", "createdat", "updatedat") VALUES (4, 'Forgecaller', 'Summons weapons mid-combat from flames and molten steel. Hot-headed, literally.', 14, 10, 15, 10, 8, 8, '2025-07-29T04:22:53.890Z', '2025-07-29T04:22:53.890Z');
INSERT INTO "class" ("id", "name", "description", "strengthbonus", "dexteritybonus", "constitutionbonus", "intelligencebonus", "wisdombonus", "charismabonus", "createdat", "updatedat") VALUES (5, 'Venom Vicar', 'Preaches sermons of sin... and syringes.', 8, 12, 10, 13, 15, 9, '2025-07-29T04:22:53.890Z', '2025-07-29T04:22:53.890Z');
INSERT INTO "class" ("id", "name", "description", "strengthbonus", "dexteritybonus", "constitutionbonus", "intelligencebonus", "wisdombonus", "charismabonus", "createdat", "updatedat") VALUES (6, 'Bog Druid', 'Smells like wet leaves. Fights like rotting vengeance. Brings frogs to a sword fight.', 10, 10, 13, 9, 15, 8, '2025-07-29T04:22:53.890Z', '2025-07-29T04:22:53.890Z');
INSERT INTO "class" ("id", "name", "description", "strengthbonus", "dexteritybonus", "constitutionbonus", "intelligencebonus", "wisdombonus", "charismabonus", "createdat", "updatedat") VALUES (7, 'Sponge Squire', 'Absorbs blows and insults with equal efficiency. Secretly hydrophobic.', 12, 13, 14, 8, 8, 10, '2025-07-29T04:22:53.890Z', '2025-07-29T04:22:53.890Z');
INSERT INTO "class" ("id", "name", "description", "strengthbonus", "dexteritybonus", "constitutionbonus", "intelligencebonus", "wisdombonus", "charismabonus", "createdat", "updatedat") VALUES (8, 'Tooth Herald', 'Commands the battlefield with blinding smiles and bludgeoning plaque.', 13, 12, 12, 9, 10, 8, '2025-07-29T04:22:53.890Z', '2025-07-29T04:22:53.890Z');
INSERT INTO "class" ("id", "name", "description", "strengthbonus", "dexteritybonus", "constitutionbonus", "intelligencebonus", "wisdombonus", "charismabonus", "createdat", "updatedat") VALUES (9, 'Crumb Knight', 'Carbs are courage. Wears gluten with pride. May contain traces of bravery.', 14, 10, 14, 8, 10, 8, '2025-07-29T04:22:53.890Z', '2025-07-29T04:22:53.890Z');
INSERT INTO "class" ("id", "name", "description", "strengthbonus", "dexteritybonus", "constitutionbonus", "intelligencebonus", "wisdombonus", "charismabonus", "createdat", "updatedat") VALUES (10, 'Ink Witch', 'Writes curses mid-fight. Books don''t just hurt your feelings — now they bite.', 8, 12, 10, 15, 10, 10, '2025-07-29T04:22:53.890Z', '2025-07-29T04:22:53.890Z');
INSERT INTO "class" ("id", "name", "description", "strengthbonus", "dexteritybonus", "constitutionbonus", "intelligencebonus", "wisdombonus", "charismabonus", "createdat", "updatedat") VALUES (11, 'Fighter', 'Trained in every weapon. Masters of grit and steel. Always ready, never flashy.', 15, 13, 14, 8, 8, 8, '2025-07-29T04:22:53.890Z', '2025-07-29T04:22:53.890Z');
INSERT INTO "class" ("id", "name", "description", "strengthbonus", "dexteritybonus", "constitutionbonus", "intelligencebonus", "wisdombonus", "charismabonus", "createdat", "updatedat") VALUES (12, 'Wizard', 'Studies ancient tomes and makes them explode. Big hat = big intellect.', 8, 10, 10, 15, 13, 9, '2025-07-29T04:22:53.890Z', '2025-07-29T04:22:53.890Z');
INSERT INTO "class" ("id", "name", "description", "strengthbonus", "dexteritybonus", "constitutionbonus", "intelligencebonus", "wisdombonus", "charismabonus", "createdat", "updatedat") VALUES (13, 'Ranger', 'One with the woods, one with the wild. And their aim? Unnatural.', 10, 15, 13, 8, 12, 9, '2025-07-29T04:22:53.890Z', '2025-07-29T04:22:53.890Z');
INSERT INTO "class" ("id", "name", "description", "strengthbonus", "dexteritybonus", "constitutionbonus", "intelligencebonus", "wisdombonus", "charismabonus", "createdat", "updatedat") VALUES (14, 'Paladin', 'Divine justice with plate armor. Smiles politely while smiting evil.', 14, 10, 14, 8, 12, 8, '2025-07-29T04:22:53.890Z', '2025-07-29T04:22:53.890Z');
INSERT INTO "class" ("id", "name", "description", "strengthbonus", "dexteritybonus", "constitutionbonus", "intelligencebonus", "wisdombonus", "charismabonus", "createdat", "updatedat") VALUES (15, 'Sorcerer', 'Power flows from within—often explosively.', 8, 12, 10, 15, 10, 10, '2025-07-29T04:22:53.890Z', '2025-07-29T04:22:53.890Z');
INSERT INTO "class" ("id", "name", "description", "strengthbonus", "dexteritybonus", "constitutionbonus", "intelligencebonus", "wisdombonus", "charismabonus", "createdat", "updatedat") VALUES (16, 'Rogue', 'If you saw them, they messed up. Sneaky, stabby, stylish.', 10, 15, 12, 10, 8, 8, '2025-07-29T04:22:53.890Z', '2025-07-29T04:22:53.890Z');
INSERT INTO "class" ("id", "name", "description", "strengthbonus", "dexteritybonus", "constitutionbonus", "intelligencebonus", "wisdombonus", "charismabonus", "createdat", "updatedat") VALUES (17, 'Cleric', 'Heals the wounded, smites the wicked, and still makes time for afternoon prayers.', 10, 10, 13, 8, 15, 11, '2025-07-29T04:22:53.890Z', '2025-07-29T04:22:53.890Z');
INSERT INTO "class" ("id", "name", "description", "strengthbonus", "dexteritybonus", "constitutionbonus", "intelligencebonus", "wisdombonus", "charismabonus", "createdat", "updatedat") VALUES (18, 'Druid', 'Talks to trees. Turns into bears. May or may not be dating a dryad.', 8, 12, 12, 10, 15, 10, '2025-07-29T04:22:53.890Z', '2025-07-29T04:22:53.890Z');
INSERT INTO "class" ("id", "name", "description", "strengthbonus", "dexteritybonus", "constitutionbonus", "intelligencebonus", "wisdombonus", "charismabonus", "createdat", "updatedat") VALUES (19, 'Bard', 'Their songs can charm, inspire, or start bar fights. Sometimes all three.', 8, 13, 10, 10, 10, 15, '2025-07-29T04:22:53.890Z', '2025-07-29T04:22:53.890Z');
INSERT INTO "class" ("id", "name", "description", "strengthbonus", "dexteritybonus", "constitutionbonus", "intelligencebonus", "wisdombonus", "charismabonus", "createdat", "updatedat") VALUES (20, 'Barbarian', 'Rage first, question never. Smells like blood and pine sap.', 15, 13, 14, 8, 8, 8, '2025-07-29T04:22:53.890Z', '2025-07-29T04:22:53.890Z');
INSERT INTO "class" ("id", "name", "description", "strengthbonus", "dexteritybonus", "constitutionbonus", "intelligencebonus", "wisdombonus", "charismabonus", "createdat", "updatedat") VALUES (21, 'Monk', 'Fists of fury, soul of calm. Every movement is poetry—until it punches your ribs in half.', 8, 15, 13, 10, 10, 8, '2025-07-29T04:22:53.890Z', '2025-07-29T04:22:53.890Z');
INSERT INTO "class" ("id", "name", "description", "strengthbonus", "dexteritybonus", "constitutionbonus", "intelligencebonus", "wisdombonus", "charismabonus", "createdat", "updatedat") VALUES (22, 'Warlock', 'Power borrowed from something ancient. Eyes that glow, secrets that burn.', 10, 14, 13, 8, 10, 10, '2025-07-29T04:22:53.890Z', '2025-07-29T04:22:53.890Z');
INSERT INTO "class" ("id", "name", "description", "strengthbonus", "dexteritybonus", "constitutionbonus", "intelligencebonus", "wisdombonus", "charismabonus", "createdat", "updatedat") VALUES (23, 'Necromancer', 'Makes friends… from corpses. Not great at parties. Excellent at revenge.', 8, 12, 14, 14, 8, 10, '2025-07-29T04:22:53.890Z', '2025-07-29T04:22:53.890Z');
INSERT INTO "class" ("id", "name", "description", "strengthbonus", "dexteritybonus", "constitutionbonus", "intelligencebonus", "wisdombonus", "charismabonus", "createdat", "updatedat") VALUES (24, 'Beastmaster', 'They growl. Their pet growls. Everything else whimpers and runs.', 8, 12, 14, 14, 8, 10, '2025-07-29T04:22:53.890Z', '2025-07-29T04:22:53.890Z');
INSERT INTO "class" ("id", "name", "description", "strengthbonus", "dexteritybonus", "constitutionbonus", "intelligencebonus", "wisdombonus", "charismabonus", "createdat", "updatedat") VALUES (25, 'Enchanter', 'Turns blades dull, voices sweet, and enemies into fans.', 10, 14, 13, 8, 10, 10, '2025-07-29T04:22:53.890Z', '2025-07-29T04:22:53.890Z');
INSERT INTO "class" ("id", "name", "description", "strengthbonus", "dexteritybonus", "constitutionbonus", "intelligencebonus", "wisdombonus", "charismabonus", "createdat", "updatedat") VALUES (26, 'Assassin', 'You''ll never hear them coming. If you do... it’s already too late.', 8, 12, 14, 14, 8, 10, '2025-07-29T04:22:53.890Z', '2025-07-29T04:22:53.890Z');
INSERT INTO "class" ("id", "name", "description", "strengthbonus", "dexteritybonus", "constitutionbonus", "intelligencebonus", "wisdombonus", "charismabonus", "createdat", "updatedat") VALUES (27, 'Elementalist', 'Bends nature’s fury into bite-sized spells. Has no chill. Except when casting Frost Nova.', 10, 14, 13, 8, 10, 10, '2025-07-29T04:22:53.890Z', '2025-07-29T04:22:53.890Z');
INSERT INTO "class" ("id", "name", "description", "strengthbonus", "dexteritybonus", "constitutionbonus", "intelligencebonus", "wisdombonus", "charismabonus", "createdat", "updatedat") VALUES (28, 'Spellsword', 'The perfect mix of stab and zap. Stylish, versatile, deadly.', 8, 12, 14, 14, 8, 10, '2025-07-29T04:22:53.890Z', '2025-07-29T04:22:53.890Z');
INSERT INTO "class" ("id", "name", "description", "strengthbonus", "dexteritybonus", "constitutionbonus", "intelligencebonus", "wisdombonus", "charismabonus", "createdat", "updatedat") VALUES (29, 'Warden', 'Protector of the wilds and the weak. Watchful, wise, and wicked with a spear.', 8, 12, 14, 14, 8, 10, '2025-07-29T04:22:53.890Z', '2025-07-29T04:22:53.890Z');
INSERT INTO "class" ("id", "name", "description", "strengthbonus", "dexteritybonus", "constitutionbonus", "intelligencebonus", "wisdombonus", "charismabonus", "createdat", "updatedat") VALUES (30, 'Blood Mage', 'Life is power—especially their own. The cost is pain. The payoff is terrifying.', 15, 13, 14, 8, 8, 8, '2025-07-29T04:22:53.890Z', '2025-07-29T04:22:53.890Z');
INSERT INTO "class" ("id", "name", "description", "strengthbonus", "dexteritybonus", "constitutionbonus", "intelligencebonus", "wisdombonus", "charismabonus", "createdat", "updatedat") VALUES (31, 'Beemancer', 'Summons swarms, hexes with honey, and stings with spite.', 8, 12, 14, 14, 8, 10, '2025-07-29T04:22:53.890Z', '2025-07-29T04:22:53.890Z');
INSERT INTO "class" ("id", "name", "description", "strengthbonus", "dexteritybonus", "constitutionbonus", "intelligencebonus", "wisdombonus", "charismabonus", "createdat", "updatedat") VALUES (32, 'Wheelwright of Destiny', 'Fate turns on a wheel—and so do enemies when this class rolls into combat.', 8, 15, 13, 10, 10, 8, '2025-07-29T04:22:53.890Z', '2025-07-29T04:22:53.890Z');
INSERT INTO "class" ("id", "name", "description", "strengthbonus", "dexteritybonus", "constitutionbonus", "intelligencebonus", "wisdombonus", "charismabonus", "createdat", "updatedat") VALUES (33, 'Mildew Monk', 'Channels decay to rot foes’ weapons and resolve. Somehow always moist.', 13, 10, 14, 10, 10, 8, '2025-07-29T04:22:53.890Z', '2025-07-29T04:22:53.890Z');
INSERT INTO "class" ("id", "name", "description", "strengthbonus", "dexteritybonus", "constitutionbonus", "intelligencebonus", "wisdombonus", "charismabonus", "createdat", "updatedat") VALUES (34, 'Meat Mage', 'Casts spells using cuts of meat. Summons spectral bacon.', 13, 10, 14, 10, 10, 8, '2025-07-29T04:22:53.890Z', '2025-07-29T04:22:53.890Z');
INSERT INTO "class" ("id", "name", "description", "strengthbonus", "dexteritybonus", "constitutionbonus", "intelligencebonus", "wisdombonus", "charismabonus", "createdat", "updatedat") VALUES (35, 'Boxmancer', 'Master of containment. Can summon, vanish, and weaponize crates.', 8, 15, 13, 10, 10, 8, '2025-07-29T04:22:53.890Z', '2025-07-29T04:22:53.890Z');
INSERT INTO "class" ("id", "name", "description", "strengthbonus", "dexteritybonus", "constitutionbonus", "intelligencebonus", "wisdombonus", "charismabonus", "createdat", "updatedat") VALUES (36, 'Gambler', 'Every attack is a game of chance—but the house usually loses.', 8, 15, 13, 10, 10, 8, '2025-07-29T04:22:53.890Z', '2025-07-29T04:22:53.890Z');
INSERT INTO "class" ("id", "name", "description", "strengthbonus", "dexteritybonus", "constitutionbonus", "intelligencebonus", "wisdombonus", "charismabonus", "createdat", "updatedat") VALUES (37, 'Disco Knight', 'Fights with rhythm and radiant damage. Once you hear their entrance music, it’s already too late.', 8, 15, 13, 10, 10, 8, '2025-07-29T04:22:53.890Z', '2025-07-29T04:22:53.890Z');
INSERT INTO "class" ("id", "name", "description", "strengthbonus", "dexteritybonus", "constitutionbonus", "intelligencebonus", "wisdombonus", "charismabonus", "createdat", "updatedat") VALUES (38, 'Cluckadin', 'Divine protector of the coop. Smite first, squawk questions later.', 8, 12, 14, 14, 8, 10, '2025-07-29T04:22:53.890Z', '2025-07-29T04:22:53.890Z');
INSERT INTO "class" ("id", "name", "description", "strengthbonus", "dexteritybonus", "constitutionbonus", "intelligencebonus", "wisdombonus", "charismabonus", "createdat", "updatedat") VALUES (39, 'Lucksmith', 'Twists fate like a pretzel. Buffs allies with improbable luck.', 10, 14, 13, 8, 10, 10, '2025-07-29T04:22:53.890Z', '2025-07-29T04:22:53.890Z');
INSERT INTO "class" ("id", "name", "description", "strengthbonus", "dexteritybonus", "constitutionbonus", "intelligencebonus", "wisdombonus", "charismabonus", "createdat", "updatedat") VALUES (40, 'Threadwalker', 'Bends the narrative to their will. Can ''snip'' enemies or ''sew'' outcomes.', 13, 10, 14, 10, 10, 8, '2025-07-29T04:22:53.890Z', '2025-07-29T04:22:53.890Z');
INSERT INTO "class" ("id", "name", "description", "strengthbonus", "dexteritybonus", "constitutionbonus", "intelligencebonus", "wisdombonus", "charismabonus", "createdat", "updatedat") VALUES (41, 'Innkeeper', 'Master of morale and rest. Can conjure food, boost stamina, and knows everyone’s secrets.', 8, 15, 13, 10, 10, 8, '2025-07-29T04:22:53.890Z', '2025-07-29T04:22:53.890Z');
INSERT INTO "class" ("id", "name", "description", "strengthbonus", "dexteritybonus", "constitutionbonus", "intelligencebonus", "wisdombonus", "charismabonus", "createdat", "updatedat") VALUES (42, 'Blacksmith', 'Repairs gear mid-battle. Can summon anvils and forge weapons in seconds.', 8, 12, 14, 14, 8, 10, '2025-07-29T04:22:53.890Z', '2025-07-29T04:22:53.890Z');
INSERT INTO "class" ("id", "name", "description", "strengthbonus", "dexteritybonus", "constitutionbonus", "intelligencebonus", "wisdombonus", "charismabonus", "createdat", "updatedat") VALUES (43, 'Tailor', 'Mends armor, weaves spell-resistant cloth, and stitches status effects into enemies.', 8, 15, 13, 10, 10, 8, '2025-07-29T04:22:53.890Z', '2025-07-29T04:22:53.890Z');
INSERT INTO "class" ("id", "name", "description", "strengthbonus", "dexteritybonus", "constitutionbonus", "intelligencebonus", "wisdombonus", "charismabonus", "createdat", "updatedat") VALUES (44, 'Baker', 'Bakes buffing buns and explosive sourdough.', 10, 14, 13, 8, 10, 10, '2025-07-29T04:22:53.890Z', '2025-07-29T04:22:53.890Z');
INSERT INTO "class" ("id", "name", "description", "strengthbonus", "dexteritybonus", "constitutionbonus", "intelligencebonus", "wisdombonus", "charismabonus", "createdat", "updatedat") VALUES (45, 'Archivist', 'Unleashes forgotten knowledge. Buffs allies and deciphers dungeon runes.', 10, 14, 13, 8, 10, 10, '2025-07-29T04:22:53.890Z', '2025-07-29T04:22:53.890Z');
INSERT INTO "class" ("id", "name", "description", "strengthbonus", "dexteritybonus", "constitutionbonus", "intelligencebonus", "wisdombonus", "charismabonus", "createdat", "updatedat") VALUES (46, 'Chamberlain', 'Optimizes allies’ cooldowns and organizes the battlefield like a ballroom.', 8, 15, 13, 10, 10, 8, '2025-07-29T04:22:53.890Z', '2025-07-29T04:22:53.890Z');
INSERT INTO "class" ("id", "name", "description", "strengthbonus", "dexteritybonus", "constitutionbonus", "intelligencebonus", "wisdombonus", "charismabonus", "createdat", "updatedat") VALUES (47, 'Stablemaster', 'Summons and controls mounts. Can trample enemies with spectral steeds.', 13, 10, 14, 10, 10, 8, '2025-07-29T04:22:53.890Z', '2025-07-29T04:22:53.890Z');
INSERT INTO "class" ("id", "name", "description", "strengthbonus", "dexteritybonus", "constitutionbonus", "intelligencebonus", "wisdombonus", "charismabonus", "createdat", "updatedat") VALUES (48, 'Scullion', 'Cleans up messes… including enemies. Removes debuffs, throws scalding soup.', 8, 12, 14, 14, 8, 10, '2025-07-29T04:22:53.890Z', '2025-07-29T04:22:53.890Z');
INSERT INTO "class" ("id", "name", "description", "strengthbonus", "dexteritybonus", "constitutionbonus", "intelligencebonus", "wisdombonus", "charismabonus", "createdat", "updatedat") VALUES (49, 'Merchant', 'Deals in buffs, bribes, and bargains. Can summon a pop-up market.', 8, 15, 13, 10, 10, 8, '2025-07-29T04:22:53.890Z', '2025-07-29T04:22:53.890Z');
INSERT INTO "class" ("id", "name", "description", "strengthbonus", "dexteritybonus", "constitutionbonus", "intelligencebonus", "wisdombonus", "charismabonus", "createdat", "updatedat") VALUES (50, 'Playwright', 'Rewrites the battlefield. Can alter initiative and invoke plot armor.', 8, 12, 14, 14, 8, 10, '2025-07-29T04:22:53.890Z', '2025-07-29T04:22:53.890Z');
INSERT INTO "class" ("id", "name", "description", "strengthbonus", "dexteritybonus", "constitutionbonus", "intelligencebonus", "wisdombonus", "charismabonus", "createdat", "updatedat") VALUES (51, 'Pyro-Bardian', 'Shouts power chords mid-berserk rage. Deals damage by riff and by roar.', 15, 13, 14, 8, 8, 8, '2025-07-29T04:22:53.890Z', '2025-07-29T04:22:53.890Z');
INSERT INTO "class" ("id", "name", "description", "strengthbonus", "dexteritybonus", "constitutionbonus", "intelligencebonus", "wisdombonus", "charismabonus", "createdat", "updatedat") VALUES (52, 'Necromelter', 'Raises the dairy-dead and spreads curdled fear.', 10, 14, 13, 8, 10, 10, '2025-07-29T04:22:53.890Z', '2025-07-29T04:22:53.890Z');
INSERT INTO "class" ("id", "name", "description", "strengthbonus", "dexteritybonus", "constitutionbonus", "intelligencebonus", "wisdombonus", "charismabonus", "createdat", "updatedat") VALUES (53, 'Stitchguard', 'Mends more than armor—mends souls. Protects allies with blessed quilting.', 15, 13, 14, 8, 8, 8, '2025-07-29T04:22:53.890Z', '2025-07-29T04:22:53.890Z');
INSERT INTO "class" ("id", "name", "description", "strengthbonus", "dexteritybonus", "constitutionbonus", "intelligencebonus", "wisdombonus", "charismabonus", "createdat", "updatedat") VALUES (54, 'Bogwarden', 'Defends sacred wetlands with muck, croaks, and vines.', 13, 10, 14, 10, 10, 8, '2025-07-29T04:22:53.890Z', '2025-07-29T04:22:53.890Z');
INSERT INTO "class" ("id", "name", "description", "strengthbonus", "dexteritybonus", "constitutionbonus", "intelligencebonus", "wisdombonus", "charismabonus", "createdat", "updatedat") VALUES (55, 'Forgecaster', 'Spellcraft built on sparks and steel. Creates living weapons of flame and fury.', 8, 12, 14, 14, 8, 10, '2025-07-29T04:22:53.890Z', '2025-07-29T04:22:53.890Z');
INSERT INTO "class" ("id", "name", "description", "strengthbonus", "dexteritybonus", "constitutionbonus", "intelligencebonus", "wisdombonus", "charismabonus", "createdat", "updatedat") VALUES (56, 'Swarmblade', 'Sneaks in with silence, swarms out with bees. Stings. Disappears. Repeats.', 13, 10, 14, 10, 10, 8, '2025-07-29T04:22:53.890Z', '2025-07-29T04:22:53.890Z');
INSERT INTO "class" ("id", "name", "description", "strengthbonus", "dexteritybonus", "constitutionbonus", "intelligencebonus", "wisdombonus", "charismabonus", "createdat", "updatedat") VALUES (57, 'Drunken Fist Fool', 'Staggers like a fool, strikes like a master.', 8, 12, 14, 14, 8, 10, '2025-07-29T04:22:53.890Z', '2025-07-29T04:22:53.890Z');
INSERT INTO "class" ("id", "name", "description", "strengthbonus", "dexteritybonus", "constitutionbonus", "intelligencebonus", "wisdombonus", "charismabonus", "createdat", "updatedat") VALUES (58, 'Packlord', 'Weaponizes inventory. Can sell mid-fight and ship pain express.', 8, 15, 13, 10, 10, 8, '2025-07-29T04:22:53.890Z', '2025-07-29T04:22:53.890Z');
INSERT INTO "class" ("id", "name", "description", "strengthbonus", "dexteritybonus", "constitutionbonus", "intelligencebonus", "wisdombonus", "charismabonus", "createdat", "updatedat") VALUES (59, 'Bloodscribe', 'Channels life force into forbidden lore. Writes spells in their own veins.', 8, 15, 13, 10, 10, 8, '2025-07-29T04:22:53.890Z', '2025-07-29T04:22:53.890Z');
INSERT INTO "class" ("id", "name", "description", "strengthbonus", "dexteritybonus", "constitutionbonus", "intelligencebonus", "wisdombonus", "charismabonus", "createdat", "updatedat") VALUES (60, 'Crumbfighter', 'Bashes with bread. Slashes with rolling pins. Toasts victory with buns of justice.', 13, 10, 14, 10, 10, 8, '2025-07-29T04:22:53.890Z', '2025-07-29T04:22:53.890Z');
INSERT INTO "classoutfit" ("id", "classid", "description", "createdat") VALUES (1, 1, 'Sleeveless chainmail over a crushed velvet doublet with skull motifs and a lute-axe combo.', '2025-07-29T04:22:53.890Z');
