INSERT INTO "classoutfit" ("id", "classid", "description", "createdat") VALUES (19, 19, 'Bright doublet, puffy shirt, feathered hat, jangling belts.', '2025-07-29T04:22:53.890Z');
INSERT INTO "classoutfit" ("id", "classid", "description", "createdat") VALUES (20, 20, 'Fur-lined vest, leather kilt, massive axe.', '2025-07-29T04:22:53.890Z');
INSERT INTO "classoutfit" ("id", "classid", "description", "createdat") VALUES (21, 21, 'Simple linen robes tied with a sash, barefoot with wrapped ankles and wrists, and a wooden prayer bead necklace clacking softly as they move.', '2025-07-29T04:22:53.890Z');
INSERT INTO "classoutfit" ("id", "classid", "description", "createdat") VALUES (22, 22, 'Tattered noble cloak over dark, tailored garments etched with infernal or eldritch patterns. A living mark pulses somewhere on their skin.', '2025-07-29T04:22:53.890Z');
INSERT INTO "classoutfit" ("id", "classid", "description", "createdat") VALUES (23, 23, 'Faded black robes adorned with bone clasps, fingerless gloves stained with embalming fluid, and a skull-topped staff that whispers.', '2025-07-29T04:22:53.890Z');
INSERT INTO "classoutfit" ("id", "classid", "description", "createdat") VALUES (24, 24, 'Furs draped over leather armor, feathered pauldrons, and a fang necklace from their first bonded beast. Often accompanied by growls.', '2025-07-29T04:22:53.890Z');
INSERT INTO "classoutfit" ("id", "classid", "description", "createdat") VALUES (25, 25, 'Silk robe interwoven with silver filaments and shifting runes, gloves enchanted to shimmer with glamor, and a crystal chime belt.', '2025-07-29T04:22:53.890Z');
INSERT INTO "classoutfit" ("id", "classid", "description", "createdat") VALUES (26, 26, 'Matte leather armor stitched for silence, cloak that blends into shadow, and a half-mask carved like a blank face.', '2025-07-29T04:22:53.890Z');
INSERT INTO "classoutfit" ("id", "classid", "description", "createdat") VALUES (27, 27, 'Robes in quadrants of red, blue, green, and brown—fire, ice, wind, and stone—each glowing faintly with elemental energy.', '2025-07-29T04:22:53.890Z');
INSERT INTO "classoutfit" ("id", "classid", "description", "createdat") VALUES (28, 28, 'Half-plate with arcane runes etched into the pauldrons, robes beneath, and a glowing sword sheathed across the back.', '2025-07-29T04:22:53.890Z');
INSERT INTO "classoutfit" ("id", "classid", "description", "createdat") VALUES (29, 29, 'Camouflaged armor of bark and hide, a heavy green cloak, and a falcon feather circlet denoting rank among wild protectors.', '2025-07-29T04:22:53.890Z');
INSERT INTO "classoutfit" ("id", "classid", "description", "createdat") VALUES (30, 30, 'Robes dyed red and black, etched with scars and ritual sigils. Arm wraps often soaked with dried blood.', '2025-07-29T04:22:53.890Z');
INSERT INTO "classoutfit" ("id", "classid", "description", "createdat") VALUES (31, 31, 'Puffy yellow-and-black striped robe, honeycomb pauldrons, and a translucent beekeeper veil shimmering with pollen motes.', '2025-07-29T04:22:53.890Z');
INSERT INTO "classoutfit" ("id", "classid", "description", "createdat") VALUES (32, 32, 'Grease-streaked apron, gear-shaped shoulder guards, and a wagon wheel strapped to their back like a divine halo.', '2025-07-29T04:22:53.890Z');
INSERT INTO "classoutfit" ("id", "classid", "description", "createdat") VALUES (33, 33, 'Moss-stained robe with moldy fringes, a belt of fungus jars, and sandals that squish ominously.', '2025-07-29T04:22:53.890Z');
INSERT INTO "classoutfit" ("id", "classid", "description", "createdat") VALUES (34, 34, 'Apron stitched from jerky, butcher’s boots, and a bacon-slice sash. Every pocket contains emergency meat.', '2025-07-29T04:22:53.890Z');
INSERT INTO "classoutfit" ("id", "classid", "description", "createdat") VALUES (35, 35, 'Corrugated armor, cardboard helm, and a mail label cape reading “fragile” in glowing runes.', '2025-07-29T04:22:53.890Z');
INSERT INTO "classoutfit" ("id", "classid", "description", "createdat") VALUES (36, 36, 'Velvet vest covered in gold embroidery, dice buttons, and a cape that always seems to flutter dramatically.', '2025-07-29T04:22:53.890Z');
INSERT INTO "classoutfit" ("id", "classid", "description", "createdat") VALUES (37, 37, 'Mirrored breastplate that reflects rainbow light, bell-bottom greaves, and a chainmail disco-ball helm.', '2025-07-29T04:22:53.890Z');
INSERT INTO "classoutfit" ("id", "classid", "description", "createdat") VALUES (38, 38, 'White-feather tabard, egg-shaped shield, beaked helm, and armor blessed by the Holy Coop.', '2025-07-29T04:22:53.890Z');
INSERT INTO "classoutfit" ("id", "classid", "description", "createdat") VALUES (39, 39, 'Patchwork coat covered in rabbit feet, clovers, dice charms, and pockets filled with chance.', '2025-07-29T04:22:53.890Z');
INSERT INTO "classoutfit" ("id", "classid", "description", "createdat") VALUES (40, 40, 'Cloak made from ever-moving threads of every color, needle-stitched boots, and a scarf that tangles time.', '2025-07-29T04:22:53.890Z');
INSERT INTO "classoutfit" ("id", "classid", "description", "createdat") VALUES (41, 41, 'Stained apron over quilted tunic, ring of iron keys, mug hook on the belt, and a welcoming, worn smile.', '2025-07-29T04:22:53.890Z');
INSERT INTO "classoutfit" ("id", "classid", "description", "createdat") VALUES (42, 42, 'Charcoal-smeared leather apron, soot-covered gloves, metal-rimmed boots, and a belt full of tongs and chisels.', '2025-07-29T04:22:53.890Z');
INSERT INTO "classoutfit" ("id", "classid", "description", "createdat") VALUES (43, 43, 'Doublet covered in pins and spools, scissors sheath at the hip, and an enchanted measuring tape coiled at the neck.', '2025-07-29T04:22:53.890Z');
