INSERT INTO "classoutfit" ("id", "classid", "description", "createdat") VALUES (45, 45, 'Dusty scholar robes, oversized glasses, scroll satchels under each arm, and ink stains as battle scars.', '2025-07-29T04:22:53.890Z');
INSERT INTO "classoutfit" ("id", "classid", "description", "createdat") VALUES (46, 46, 'Crisp livery, spotless gloves, scroll case with emergency policies, and a lapel pin of authority.', '2025-07-29T04:22:53.890Z');
INSERT INTO "classoutfit" ("id", "classid", "description", "createdat") VALUES (47, 47, 'Rough wool cloak, reinforced boots, leather gloves with reins etched into the palms, and saddle polish on everything.', '2025-07-29T04:22:53.890Z');
INSERT INTO "classoutfit" ("id", "classid", "description", "createdat") VALUES (48, 48, 'Ripped apron soaked in dishwater, bucket helm that still leaks, and a ladle that doubles as a warhammer.', '2025-07-29T04:22:53.890Z');
INSERT INTO "classoutfit" ("id", "classid", "description", "createdat") VALUES (49, 49, 'Vest lined with hidden pockets, gold-trimmed cloak, jingling coin boots, and a monocle that appraises souls.', '2025-07-29T04:22:53.890Z');
INSERT INTO "classoutfit" ("id", "classid", "description", "createdat") VALUES (50, 50, 'Frilled collar, ink-streaked breeches, and a reversible cape bearing tragedy and comedy masks.', '2025-07-29T04:22:53.890Z');
INSERT INTO "classoutfit" ("id", "classid", "description", "createdat") VALUES (51, 51, 'Charred leather armor stitched with lute strings, flaming pauldrons, and a battle-lute strapped over the back.', '2025-07-29T04:22:53.890Z');
INSERT INTO "classoutfit" ("id", "classid", "description", "createdat") VALUES (52, 52, 'Black robes with bubbling cheese runes, skull-shaped fondue pot helm, and gauntlets made of aged brie.', '2025-07-29T04:22:53.890Z');
INSERT INTO "classoutfit" ("id", "classid", "description", "createdat") VALUES (53, 53, 'Armor quilted with holy threads, a shield patched with blessings, and a sacred sewing needle as a holy symbol.', '2025-07-29T04:22:53.890Z');
INSERT INTO "classoutfit" ("id", "classid", "description", "createdat") VALUES (54, 54, 'Cloak of reeds and swamp grass, frog-skull pauldrons, and boots that squelch when moving righteously.', '2025-07-29T04:22:53.890Z');
INSERT INTO "classoutfit" ("id", "classid", "description", "createdat") VALUES (55, 55, 'Magically tempered apron, steel-gem hybrid pauldrons, and gloves that spark with heat and mana.', '2025-07-29T04:22:53.890Z');
