INSERT INTO "classoutfit" ("id", "classid", "description", "createdat") VALUES (58, 58, 'Merchant robes reinforced with crate wood, scroll-buckles, and satchels enchanted to carry armies.', '2025-07-29T04:22:53.890Z');
