INSERT INTO "storychoice" ("id", "storynodeid", "choicetext", "nextnodeid", "metadataimpact", "createdat", "updatedat", "effects") VALUES (18, 5, 'Tuck your phone along with your clothes into the locker and set your password.', 19, ('{"security":1,"rule_following":1}')::jsonb, '2025-07-31T20:16:04.447Z', '2025-07-31T20:16:04.447Z', ('{}')::jsonb);
INSERT INTO "storychoice" ("id", "storynodeid", "choicetext", "nextnodeid", "metadataimpact", "createdat", "updatedat", "effects") VALUES (20, 5, 'Close the locker and set the password. Glance around and tuck your phone into the waist of your outfit. Hopefully it doesn''t fall out.', 19, ('{"anxiety":1,"rule_following":-1,"resourcefulness":1}')::jsonb, '2025-07-31T20:16:04.447Z', '2025-07-31T20:16:04.447Z', ('{}')::jsonb);
INSERT INTO "storychoice" ("id", "storynodeid", "choicetext", "nextnodeid", "metadataimpact", "createdat", "updatedat", "effects") VALUES (19, 5, 'Grab your clothes back out of the locker and redress- this is silly. I''m wearing my own clothes and turn to head into the faire wearing your street clothes.', 7, ('{"modern":1,"stubbornness":1,"rule_following":-1}')::jsonb, '2025-07-31T20:16:04.447Z', '2025-07-31T20:16:04.447Z', ('{"inventory_add":[{"name":"your clothes back","quantity":1}]}')::jsonb);
INSERT INTO "storychoice" ("id", "storynodeid", "choicetext", "nextnodeid", "metadataimpact", "createdat", "updatedat", "effects") VALUES (27, 7, 'Take one of the masks from a tree.', 11, ('{"theft":1,"boldness":1}')::jsonb, '2025-07-31T20:16:04.447Z', '2025-07-31T20:16:04.447Z', ('{"inventory_add":[{"name":"masks","quantity":1}]}')::jsonb);
INSERT INTO "storychoice" ("id", "storynodeid", "choicetext", "nextnodeid", "metadataimpact", "createdat", "updatedat", "effects") VALUES (1, 1, '"What a weird sign," you mutter, glancing around.
INSERT INTO "storychoice" ("id", "storynodeid", "choicetext", "nextnodeid", "metadataimpact", "createdat", "updatedat", "effects") VALUES (2, 1, 'You tug your hoodie tighter against a sudden breeze and take a hesitant step toward the fairgrounds. The gates yawn open, unmanned. There''s no ticket booth, no staff, just… music. Faint flute and drumbeats drift on the wind. "Maybe they''re already inside," you murmur, trying not to feel like you''re walking into a trap.', 2, ('{"anxiety":1,"personality":"adventurous"}')::jsonb, '2025-07-31T20:16:04.447Z', '2025-07-31T20:16:04.447Z', ('{}')::jsonb);
INSERT INTO "storychoice" ("id", "storynodeid", "choicetext", "nextnodeid", "metadataimpact", "createdat", "updatedat", "effects") VALUES (3, 1, 'You circle the sign, half-expecting a prank camera crew or a bored medieval LARPer to jump out yelling "Gotcha!" But there''s nothing—just that odd silence you only notice when it''s unnatural. Your shoes crunch gravel as you walk a little further in. You pass through the gates before you can talk yourself out of it.', 2, ('{"curiosity":1,"personality":"skeptical"}')::jsonb, '2025-07-31T20:16:04.447Z', '2025-07-31T20:16:04.447Z', ('{}')::jsonb);
INSERT INTO "storychoice" ("id", "storynodeid", "choicetext", "nextnodeid", "metadataimpact", "createdat", "updatedat", "effects") VALUES (4, 1, 'You reach out and touch the sign. The wood feels oddly warm. As you pull your hand back, a shimmer runs down the painted letters like rippling water. You blink. The fairgrounds seem… closer than they were before. Larger. Brighter. You take one cautious step forward, nervous but glad you decided to do this on your own.', 2, ('{"personality":"mystical","magic_affinity":1}')::jsonb, '2025-07-31T20:16:04.447Z', '2025-07-31T20:16:04.447Z', ('{}')::jsonb);
INSERT INTO "storychoice" ("id", "storynodeid", "choicetext", "nextnodeid", "metadataimpact", "createdat", "updatedat", "effects") VALUES (5, 2, 'My good sir', 3, ('{"formality":1,"gender_preference":"masculine"}')::jsonb, '2025-07-31T20:16:04.447Z', '2025-07-31T20:16:04.447Z', ('{}')::jsonb);
INSERT INTO "storychoice" ("id", "storynodeid", "choicetext", "nextnodeid", "metadataimpact", "createdat", "updatedat", "effects") VALUES (6, 2, 'Dearest madam', 3, ('{"formality":1,"gender_preference":"feminine"}')::jsonb, '2025-07-31T20:16:04.447Z', '2025-07-31T20:16:04.447Z', ('{}')::jsonb);
INSERT INTO "storychoice" ("id", "storynodeid", "choicetext", "nextnodeid", "metadataimpact", "createdat", "updatedat", "effects") VALUES (7, 2, 'Friend is fine, thank you.', 3, ('{"formality":0,"gender_preference":"neutral"}')::jsonb, '2025-07-31T20:16:04.447Z', '2025-07-31T20:16:04.447Z', ('{}')::jsonb);
