INSERT INTO "storychoice" ("id", "storynodeid", "choicetext", "nextnodeid", "metadataimpact", "createdat", "updatedat", "effects") VALUES (21, 6, 'Follow the flickering lantern to the left.', 7, ('{"caution":-1,"curiosity":1}')::jsonb, '2025-07-31T20:16:04.447Z', '2025-07-31T20:16:04.447Z', ('{}')::jsonb);
INSERT INTO "storychoice" ("id", "storynodeid", "choicetext", "nextnodeid", "metadataimpact", "createdat", "updatedat", "effects") VALUES (22, 6, 'Investigate the lantern, but keep your distance.', 7, ('{"caution":1,"curiosity":1}')::jsonb, '2025-07-31T20:16:04.447Z', '2025-07-31T20:16:04.447Z', ('{}')::jsonb);
INSERT INTO "storychoice" ("id", "storynodeid", "choicetext", "nextnodeid", "metadataimpact", "createdat", "updatedat", "effects") VALUES (23, 6, 'Head toward the sound of wheels on the right.', 8, ('{"caution":-1,"boldness":1}')::jsonb, '2025-07-31T20:16:04.447Z', '2025-07-31T20:16:04.447Z', ('{}')::jsonb);
INSERT INTO "storychoice" ("id", "storynodeid", "choicetext", "nextnodeid", "metadataimpact", "createdat", "updatedat", "effects") VALUES (24, 6, 'Wait and listen for more clues before deciding.', 8, ('{"caution":1,"patience":1}')::jsonb, '2025-07-31T20:16:04.447Z', '2025-07-31T20:16:04.447Z', ('{}')::jsonb);
INSERT INTO "storychoice" ("id", "storynodeid", "choicetext", "nextnodeid", "metadataimpact", "createdat", "updatedat", "effects") VALUES (25, 7, 'Talk to the moving mask.', 9, ('{"courage":1,"curiosity":1}')::jsonb, '2025-07-31T20:16:04.447Z', '2025-07-31T20:16:04.447Z', ('{}')::jsonb);
INSERT INTO "storychoice" ("id", "storynodeid", "choicetext", "nextnodeid", "metadataimpact", "createdat", "updatedat", "effects") VALUES (26, 7, 'Ignore it and walk faster.', 10, ('{"fear":1,"caution":1}')::jsonb, '2025-07-31T20:16:04.447Z', '2025-07-31T20:16:04.447Z', ('{}')::jsonb);
INSERT INTO "storychoice" ("id", "storynodeid", "choicetext", "nextnodeid", "metadataimpact", "createdat", "updatedat", "effects") VALUES (28, 8, 'Step inside the coach.', 10, ('{"trust":1,"curiosity":1}')::jsonb, '2025-07-31T20:16:04.447Z', '2025-07-31T20:16:04.447Z', ('{}')::jsonb);
INSERT INTO "storychoice" ("id", "storynodeid", "choicetext", "nextnodeid", "metadataimpact", "createdat", "updatedat", "effects") VALUES (29, 8, 'Climb up to talk to the driver.', 12, ('{"boldness":1,"leadership":1}')::jsonb, '2025-07-31T20:16:04.447Z', '2025-07-31T20:16:04.447Z', ('{}')::jsonb);
INSERT INTO "storychoice" ("id", "storynodeid", "choicetext", "nextnodeid", "metadataimpact", "createdat", "updatedat", "effects") VALUES (30, 8, 'Back away slowly and hide.', 13, ('{"fear":1,"caution":1}')::jsonb, '2025-07-31T20:16:04.447Z', '2025-07-31T20:16:04.447Z', ('{}')::jsonb);
INSERT INTO "storychoice" ("id", "storynodeid", "choicetext", "nextnodeid", "metadataimpact", "createdat", "updatedat", "effects") VALUES (31, 9, 'Say ''yes'' and name one of them.', 14, ('{"courage":1,"honesty":1}')::jsonb, '2025-07-31T20:16:04.447Z', '2025-07-31T20:16:04.447Z', ('{}')::jsonb);
INSERT INTO "storychoice" ("id", "storynodeid", "choicetext", "nextnodeid", "metadataimpact", "createdat", "updatedat", "effects") VALUES (32, 9, 'Say ''no'' and ask for more time.', 11, ('{"caution":1,"patience":1}')::jsonb, '2025-07-31T20:16:04.447Z', '2025-07-31T20:16:04.447Z', ('{}')::jsonb);
INSERT INTO "storychoice" ("id", "storynodeid", "choicetext", "nextnodeid", "metadataimpact", "createdat", "updatedat", "effects") VALUES (33, 9, 'Rip the mask from the tree.', 18, ('{"aggression":1,"impulsiveness":1}')::jsonb, '2025-07-31T20:16:04.447Z', '2025-07-31T20:16:04.447Z', ('{}')::jsonb);
