INSERT INTO "storynode" ("id", "title", "content", "nodetype", "requiresinput", "inputtype", "createdat", "updatedat") VALUES (1, 'Welcome to MYTHOS', 'Yawning from the long drive, you step out of the car and stretch your legs, groaning softly as your back pops. The air smells faintly of hay and funnel cake—strangely comforting. In the distance, the sweeping span of the Renaissance Faire stretches wide and colorful, a jarring contrast to the asphalt parking lot and roaring highway you just pulled off from.
INSERT INTO "storynode" ("id", "title", "content", "nodetype", "requiresinput", "inputtype", "createdat", "updatedat") VALUES (2, 'The Ticket Booth', 'You make your way up the gravel path toward the ticket booth.
INSERT INTO "storynode" ("id", "title", "content", "nodetype", "requiresinput", "inputtype", "createdat", "updatedat") VALUES (3, 'Your Experience', 'He nods as you respond, eyes twinkling. "Perfect, {{prompt2answer}} And here at MYTHOS, you may be anything you want to be." He gestures behind him at the towering gates with an almost conspiratorial grin. "As your journey begins, how experienced do you feel?"', 'standard', FALSE, NULL, '2025-07-31T20:16:04.447Z', '2025-07-31T20:16:04.447Z');
INSERT INTO "storynode" ("id", "title", "content", "nodetype", "requiresinput", "inputtype", "createdat", "updatedat") VALUES (4, 'Dress Code', '"Ah, wonderful. We get all sorts here—fresh squires, seasoned bards, and even a wayward noble or two." He leans in slightly, lowering his voice. "But before you enter through our gates, you''ll need to meet our dress code. Dragons, you see, are not particularly fond of machine-crafted garb. Or perhaps..."He muses a finger lightly brushing his unshaved face. "-They are too fond of machine-crafted garb. It''s really all perspective you see."
INSERT INTO "storynode" ("id", "title", "content", "nodetype", "requiresinput", "inputtype", "createdat", "updatedat") VALUES (5, 'Your Possessions', 'The outfit fits as if it were hand stitched just for you. You bend and twist surprisingly comfortable in the unfamiliar fabric. A set of lockers sits open along with a sign. Leave ye material possessions at the door. After all, there is no need for them where you are headed. Phones are not permitted inside. You shove your clothes into a locker and begin to tuck your phone into your pocket out of habit when you realize this outfit has no pockets. Uncomfortable you turn to ask the ticketmaster what you should do- but when you turn he has disappeared from view. He must have gone off to help another customer you reassure yourself.', 'standard', FALSE, NULL, '2025-07-31T20:16:04.447Z', '2025-07-31T20:16:04.447Z');
INSERT INTO "storynode" ("id", "title", "content", "nodetype", "requiresinput", "inputtype", "createdat", "updatedat") VALUES (6, 'The Crossroads', 'As you step deeper into the faire, the sounds of laughter and music grow distant. The path splits before you, and a strange mist curls around your ankles. To your left, a flickering lantern hangs from a twisted branch. To your right, you hear the faint sound of wheels on gravel.', 'standard', FALSE, NULL, '2025-07-31T20:16:04.447Z', '2025-07-31T20:16:04.447Z');
INSERT INTO "storynode" ("id", "title", "content", "nodetype", "requiresinput", "inputtype", "createdat", "updatedat") VALUES (7, 'The Masked Path', 'You follow a flickering lantern through a hedge archway. The path ahead twists, lined with wooden masks nailed to trees. One of them turns to look at you.', 'standard', FALSE, NULL, '2025-07-31T20:16:04.447Z', '2025-07-31T20:16:04.447Z');
INSERT INTO "storynode" ("id", "title", "content", "nodetype", "requiresinput", "inputtype", "createdat", "updatedat") VALUES (8, 'The Stagecoach', 'A stagecoach painted in shifting colors creaks to a halt beside you. The driver gestures wordlessly toward the open door, where a single violin plays itself.', 'standard', FALSE, NULL, '2025-07-31T20:16:04.447Z', '2025-07-31T20:16:04.447Z');
INSERT INTO "storynode" ("id", "title", "content", "nodetype", "requiresinput", "inputtype", "createdat", "updatedat") VALUES (9, 'The Whispering Mask', 'The mask whispers your name and asks, ''Do you know what you left behind?'' Images flash across its surface: a house, a mirror, a scar.', 'standard', FALSE, NULL, '2025-07-31T20:16:04.447Z', '2025-07-31T20:16:04.447Z');
INSERT INTO "storynode" ("id", "title", "content", "nodetype", "requiresinput", "inputtype", "createdat", "updatedat") VALUES (10, 'The Clock Tent', 'You stumble into a tent filled with clocks, each ticking out of sync. A sign reads: ''Pick your pace or be lost in time.''', 'standard', FALSE, NULL, '2025-07-31T20:16:04.447Z', '2025-07-31T20:16:04.447Z');
INSERT INTO "storynode" ("id", "title", "content", "nodetype", "requiresinput", "inputtype", "createdat", "updatedat") VALUES (11, 'The Unnatural Garden', 'A garden blooms in unnatural colors. Each plant seems to sway toward you. A woman in a mask kneels in the center, tending to a blue rose that pulses like a heartbeat.', 'standard', FALSE, NULL, '2025-07-31T20:16:04.447Z', '2025-07-31T20:16:04.447Z');
INSERT INTO "storynode" ("id", "title", "content", "nodetype", "requiresinput", "inputtype", "createdat", "updatedat") VALUES (12, 'The Doppelgänger Driver', 'The driver turns to reveal your own face beneath the hood. ''We''re nearly out of time,'' it says. The horses begin to scream like people.', 'standard', FALSE, NULL, '2025-07-31T20:16:04.447Z', '2025-07-31T20:16:04.447Z');
INSERT INTO "storynode" ("id", "title", "content", "nodetype", "requiresinput", "inputtype", "createdat", "updatedat") VALUES (13, 'The Puppet Stall', 'You hide beneath a puppet stall, watching legs pass by. One pair stops. A marionette drops beside you and speaks with your voice: ''Why did you run?''', 'standard', FALSE, NULL, '2025-07-31T20:16:04.447Z', '2025-07-31T20:16:04.447Z');
INSERT INTO "storynode" ("id", "title", "content", "nodetype", "requiresinput", "inputtype", "createdat", "updatedat") VALUES (14, 'The Portrait Hall', 'You reach a hallway of portraits—each depicting you, but different: older, wounded, crowned. One frame is empty and warm to the touch.', 'standard', FALSE, NULL, '2025-07-31T20:16:04.447Z', '2025-07-31T20:16:04.447Z');
INSERT INTO "storynode" ("id", "title", "content", "nodetype", "requiresinput", "inputtype", "createdat", "updatedat") VALUES (15, 'The Memory Jars', 'The air thickens. Whispers echo with things you''ve never told anyone. You see a child holding your memories in jars.', 'standard', FALSE, NULL, '2025-07-31T20:16:04.447Z', '2025-07-31T20:16:04.447Z');
INSERT INTO "storynode" ("id", "title", "content", "nodetype", "requiresinput", "inputtype", "createdat", "updatedat") VALUES (16, 'The Shimmering Gate', 'At last, a shimmering gate pulses before you. The path splits: three shadows wait. One wears your smile. One wears your regret. One wears nothing at all.', 'standard', FALSE, NULL, '2025-07-31T20:16:04.447Z', '2025-07-31T20:16:04.447Z');
INSERT INTO "storynode" ("id", "title", "content", "nodetype", "requiresinput", "inputtype", "createdat", "updatedat") VALUES (17, 'Portal Entered', 'As you step through the shimmering gate, the world around you dissolves into a kaleidoscope of colors and sensations. You feel yourself being pulled forward, transformed, becoming something new yet familiar. The journey has only just begun...', 'standard', FALSE, NULL, '2025-07-31T20:16:04.447Z', '2025-07-31T20:16:04.447Z');
INSERT INTO "storynode" ("id", "title", "content", "nodetype", "requiresinput", "inputtype", "createdat", "updatedat") VALUES (18, 'The End', 'Darkness envelops you as your choices lead to an unfortunate end. But in this realm of stories, death is merely another beginning...', 'standard', FALSE, NULL, '2025-07-31T20:16:04.447Z', '2025-07-31T20:16:04.447Z');
INSERT INTO "storynode" ("id", "title", "content", "nodetype", "requiresinput", "inputtype", "createdat", "updatedat") VALUES (19, 'Locker Password', 'You set a password for your locker. What 4-digit code do you choose?', 'standard', FALSE, NULL, '2025-07-31T20:16:04.447Z', '2025-07-31T20:16:04.447Z');
INSERT INTO "world" ("id", "name", "description", "dimensionsx", "dimensionsy", "createdat", "updatedat") VALUES (1, 'Virelia', 'A sprawling, magic-scarred continent where players can forge any path—adventurer, merchant, explorer, or loreseeker. Every coordinate has meaning, history, and danger.', 10000, 10000, '2025-07-29T20:17:31.561Z', '2025-07-29T20:17:31.561Z');
